use xiom.io;

use xiom.string;
interface Displayable {
  fn display(&self) -> Str;
}

type Fruit = { name: Str; color: Str; }
fn Fruit.display(&self) -> Str {
  let result = self.name.clone();
  let open_paren = " (";
  let close_paren = ")";
  let combined = string.str_concat(result, open_paren);
  let combined = string.str_concat(combined, self.color.clone());
  let combined = string.str_concat(combined, close_paren);
  combined
}

type Vegetable = { name: Str; season: Str; }
fn Vegetable.display(&self) -> Str {
  let result = self.name.clone();
  result
}

fn print_all[T: Displayable](items: &Vec[T]) {
  var i = 0;
  while i < items.len() {
    io.println(items.get(i).unwrap().display());
    i += 1;
  }
}

fn main() -> Int {
  let fruits: Vec[Fruit] = Vec[Fruit].new();
  fruits.push(Fruit{ name: "Apple", color: "Red" });
  print_all(&fruits);
  return 0;
}
